INSERT INTO news (title, content, category, status, image_url) VALUES (
  'В 2026 году в Таганроге на благоустройство двух парков направят 7,6 млн рублей',
  'В 2026 году на благоустройство двух парков в Таганроге — им. М. Горького и Приморского — из бюджета региона выделили 7,6 млн руб. Это следует из сообщений главы города Светланы Камбуловой, опубликованных в её Telegram-канале.

Глава города рассказала, что в этом году парк им. Горького (в центре Таганрога) снова стал победителем губернаторской программы «Сделаем вместе». «На выделенные средства — 4,2 млн руб. — будут выполнены ремонтно-реставрационные работы ограждения и южного входа в парк. Это сделает пространство ещё комфортнее и привлекательнее для всех горожан», — подчеркнула глава города.

Она добавила, что это только часть необходимых работ. Капремонта требуют чугунное и каменное ограждение парковой территории по всему периметру, Зелёный театр, ретро-павильон, сцена Танцевальной веранды и другие объекты парка. «Он является объектом культурного наследия, поэтому к решению всех задач будем подходить поэтапно с учётом требований законодательства», — заверила Светлана Камбулова.

Значимым для таганрожцев местом является и Приморский парк, который в 2017–2019 годах пережил масштабное благоустройство в рамках нацпроекта. Здесь работают детские и спортивные площадки (воркаут, минифутбол, баскетбол), авиамодельная зона и детские аттракционы, с 2024 года действует первая в Ростовской области научная детская площадка. Парк адаптирован для маломобильных групп населения. В рамках проекта «Сделаем вместе» здесь установили систему видеонаблюдения из 40 камер, что повысило уровень безопасности территории.',
  'Городские улучшения',
